<script>
function topup(){return {selected:null,amount:0,price:0,coupon:'',discount:0,couponMessage:'',couponError:false,async applyCoupon(){this.couponMessage='';this.couponError=false;if(!this.selected)return;try{const r=await fetch(@json(route('coupons.validate')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({code:this.coupon,package_id:this.selected})});const d=await r.json();if(!r.ok)throw new Error(d.message||Object.values(d.errors||{}).flat()[0]||'Could not apply code');this.discount=Number(d.discount_amount);this.coupon=d.code;this.couponMessage='Promo code applied successfully.';}catch(e){this.discount=0;this.couponError=true;this.couponMessage=e.message;}}}}
</script>
